window.BIO005_SHEET = {"1": {"title": "How physiology works and what keeps you steady", "midterm": 1, "items": [{"n": 1, "name": "Physiology and levels of function", "can": "Define physiology and place a given process at the correct level of organization from molecule to organism, then state the level at which that process is best explained.", "a": "Build your own ladder. Pick a process, not oxygen delivery, and draw it at all six levels, molecule up to organism. One small box per level, labeled. Then break one rung and write, level by level, what stops working above it.", "b": "Pick your own process, not oxygen delivery. Draw the same thing twice. First as anatomy sees it, the structures and their parts. Then as physiology sees it, the same thing working, with arrows for what moves and what changes. Under each drawing, one line naming the question it answers.", "lab": false}, {"n": 2, "name": "Structure and function relationship", "can": "Predict how a change in the structure of a molecule, cell, tissue, or organ alters its function, using examples from two different organ systems.", "a": "Draw one structure from this week and label the single feature that makes its job possible. Then sketch what would stop working if that feature changed.", "b": "List three structures from this week. Beside each, write the one property its function depends on, in six words or fewer.", "lab": true}, {"n": 3, "name": "Body fluid compartments", "can": "State the approximate volumes of total body water, intracellular fluid, extracellular fluid, plasma, and interstitial fluid in a 70 kg adult and compare the dominant solutes of the intracellular and extracellular compartments.", "a": "Draw the fluid compartments top down with the fractions. Use one border style for inside cells and a different one for outside.", "b": "On a compartment drawing, mark where a blood sample is taken and which compartment you are actually drawing a conclusion about.", "lab": true}, {"n": 4, "name": "Compartment separation and clinical volume shifts", "can": "Predict the direction of water movement between compartments when extracellular osmolarity rises or falls and name a clinical situation that produces each shift.", "a": "Draw a patient with swollen ankles and a low blood pressure. Use arrows to show where the water went.", "b": "Draw three scenarios: water gained in the vessels, water lost from the body, water moved into tissue. Predict blood pressure under each.", "lab": false}, {"n": 5, "name": "Homeostasis defined", "can": "Define homeostasis, regulated variable, and setpoint, and distinguish homeostasis from chemical equilibrium and from steady state.", "a": "Write the definition of homeostasis, then underline the three words doing the real work. Beside each underlined word, one line on why it matters.", "b": "Draw two graphs side by side, a value in steady state and a value at equilibrium. On each, label what is still moving and what it costs.", "lab": false}, {"n": 6, "name": "Mass balance", "can": "Apply the mass balance equation to a solute or to body water and calculate the intake, production, and output combination that holds the amount in the body constant.", "a": "Write the mass balance equation and label every term. Then draw a body outline with arrows in and out for sodium, labeling which arrow is which term.", "b": "Work a mass balance for one substance across one day. Then change a single term and show the new result underneath.", "lab": true}, {"n": 7, "name": "Mass flow and clearance", "can": "Calculate mass flow as concentration times volume flow, and clearance as rate of removal divided by plasma concentration, and explain why two patients with the same concentration can have very different delivery.", "a": "Write both equations from memory with the units written under every term, and show the units cancelling. Then work the two patient case: identical oxygen content, one with half the cardiac output. Numbers, not sentences.", "b": "Draw one vessel delivering to a tissue. Label the concentration and the volume flow. Draw it again with the flow halved and write what happened to delivery. Then say in one line which one you would change first in a patient, and why.", "lab": false}, {"n": 8, "name": "Feedback loop components", "can": "Diagram a negative feedback loop labeling stimulus, sensor, afferent path, integrating center, efferent path, effector, and response, and trace body temperature or blood glucose through every step.", "a": "Draw the five component reflex pathway top down and label all five plus the feedback arrow. Labels only, no sentences.", "b": "Fill in the five components for thermoregulation on a cold day. Then mark which component you would suspect first if the patient never shivered.", "lab": true}, {"n": 9, "name": "Local and reflex control pathways", "can": "Distinguish a local control pathway from a long distance reflex pathway and classify a given response as one or the other.", "a": "Draw a local control example and a reflex control example side by side. On each, mark how far the signal travels.", "b": "Standing up suddenly: draw the reflex, label all five components, and write one line on why local control could not have handled it.", "lab": false}, {"n": 10, "name": "Negative and positive feedback", "can": "Distinguish negative from positive feedback by the direction of the response and give a physiological example of each, explaining why a positive feedback loop needs an outside event to end it.", "a": "Draw one negative feedback loop and one positive feedback loop as arrow diagrams. On each, mark what makes it stop.", "b": "Draw clotting as a positive feedback loop, then show what ends it. Underneath, write one line on why the body can afford to use positive feedback here.", "lab": false}, {"n": 11, "name": "Feedforward control and acclimatization", "can": "Explain anticipatory feedforward control and acclimatization and identify which one is operating in a given scenario.", "a": "Draw a timeline of eating a meal. Mark where feedforward starts and where feedback takes over.", "b": "Draw a setpoint as a horizontal line. Show what fever does to it, and mark at each stage what the patient feels.", "lab": false}, {"n": 12, "name": "Signal types and range", "can": "Classify a chemical signal as autocrine, paracrine, neurotransmitter, neurohormone, or hormone by its route and distance of travel.", "a": "Draw one target cell in the middle of the box. Draw an arrow in from each of the five signal types, autocrine, paracrine, neurotransmitter, neurohormone, hormone. Label each arrow with how far it travelled and what carried it.", "b": "Make a five row table. Signal type, where it is released, how far it goes, what it travels through. Fill it from memory, then check one row against the book.", "lab": false}, {"n": 13, "name": "Receptor location and ligand solubility", "can": "Predict whether a signal molecule binds a surface receptor or an intracellular receptor from its lipid solubility and relate that to the speed and duration of the response.", "a": "Draw a cell with one surface receptor and one intracellular receptor. Show the path a lipid soluble signal takes and the path a water soluble one takes. Mark which response is faster and which lasts longer.", "b": "Write the two questions you would ask about any new signal molecule to predict where its receptor sits. Then answer both for a steroid and for a peptide hormone.", "lab": false}, {"n": 14, "name": "Signal amplification", "can": "Explain how a cascade amplifies a signal and estimate the size of the amplification across the steps of a given pathway.", "a": "Draw a three step cascade as a widening funnel. Put a number on each step and multiply them down the side to get the total amplification.", "b": "Start from one ligand and write the count at each step of a cascade until you reach the response. One line per step, numbers only, no sentences.", "lab": false}, {"n": 15, "name": "Receptor modulation", "can": "Define agonist, antagonist, competitive inhibition, up regulation, and down regulation, and predict the effect of chronic ligand excess on target cell sensitivity.", "a": "Draw one target cell three times. Normal, after a long stretch of scarce signal, after a long stretch of excess signal. Show the receptor count changing in each and label which is up regulation and which is down.", "b": "Define agonist, antagonist, up regulation and down regulation in your own words, one line each. Then explain in two lines why a patient who needs more opioid for the same effect is usually showing down regulation rather than drug seeking.", "lab": false}, {"n": 16, "name": "Experimental design and controls", "can": "Identify the hypothesis, independent variable, dependent variable, and control condition in a physiology experiment and state what the control rules out.", "a": "Sketch an experiment as three labeled boxes: what you changed, what you measured, and your control.", "b": "Take a claim from this week and design the control group that would test it. Draw both groups and label the one difference between them.", "lab": true}, {"n": 17, "name": "Measurement error and variability", "can": "Distinguish random from systematic error and explain why physiological measurements are repeated and averaged.", "a": "Draw two sets of repeated measurements, one with high variability and one with low. Mark which difference between readings is real.", "b": "List three sources of variation in a single measurement. Beside each, one way to reduce it.", "lab": true}, {"n": 18, "name": "Graphing and data interpretation", "can": "Construct a labeled graph with the independent variable on the x axis, and read slope, direction, and trend from a physiological data set.", "a": "Plot the mission patient's sodium across the three days. Label both axes with units and mark the reference range on the graph.", "b": "Draw a saturation curve. Label the plateau, then write one line on what the plateau means physiologically.", "lab": true}]}, "2": {"title": "The chemistry that does work in the body", "midterm": 1, "items": [{"n": 1, "name": "Water and solution properties", "can": "Explain how the polarity and hydrogen bonding of water determine solubility and identify whether a given solute is hydrophilic or hydrophobic."}, {"n": 2, "name": "pH and buffers", "can": "Define pH, state the normal pH range of arterial blood, and explain how a buffer pair resists a change in pH when acid or base is added."}, {"n": 3, "name": "Protein structure and function", "can": "Relate the levels of protein structure to binding site shape and explain how denaturation by heat or pH change destroys function."}, {"n": 4, "name": "Enzyme activity and regulation", "can": "Describe how enzymes lower activation energy and predict the effect of substrate concentration, temperature, pH, and competitive or allosteric inhibition on reaction rate."}, {"n": 5, "name": "ATP and energy coupling", "can": "Explain how ATP hydrolysis is coupled to endergonic cellular work and name three categories of work that require it."}, {"n": 6, "name": "Enzyme assay", "can": "Measure enzyme activity across a range of temperature or pH using a spectrophotometric or colorimetric assay, plot the results, and identify the optimum."}, {"n": 7, "name": "ATP production pathways", "can": "Compare glycolysis, the citric acid cycle, and oxidative phosphorylation by location, oxygen requirement, and ATP yield."}]}, "3": {"title": "Getting across the membrane", "midterm": 1, "items": [{"n": 1, "name": "Body fluid compartments", "can": "State the approximate volumes of total body water, intracellular fluid, extracellular fluid, plasma, and interstitial fluid in a 70 kg adult and compare the dominant solutes of the intracellular and extracellular compartments."}, {"n": 2, "name": "Compartment separation and clinical volume shifts", "can": "Predict the direction of water movement between compartments when extracellular osmolarity rises or falls and name a clinical situation that produces each shift."}, {"n": 3, "name": "Membrane composition and fluidity", "can": "Describe the fluid mosaic membrane and state how phospholipids, cholesterol, glycolipids, and integral and peripheral proteins contribute to its properties."}, {"n": 4, "name": "Determinants of permeability", "can": "Rank molecules by their ability to cross a lipid bilayer unaided using size, charge, and lipid solubility, and predict which will require a protein."}, {"n": 5, "name": "Simple diffusion and Fick's law", "can": "State the variables in Fick's law of diffusion and predict how a change in concentration gradient, surface area, membrane thickness, or distance changes the rate of transfer."}, {"n": 6, "name": "Osmolarity and tonicity", "can": "Calculate the osmolarity of a solution, distinguish osmolarity from tonicity, and classify a solution as isotonic, hypotonic, or hypertonic to a cell."}, {"n": 7, "name": "Osmosis and cell volume", "can": "Predict the direction of water movement and the resulting change in cell volume when a cell is placed in a solution of stated osmolarity and penetrating solute content."}, {"n": 8, "name": "Diffusion and osmosis experiment", "can": "Measure diffusion and osmotic movement across a selectively permeable membrane and relate the observed rate to molecular size and concentration gradient."}, {"n": 9, "name": "Tonicity and red blood cells", "can": "Observe erythrocytes in solutions of different tonicity, identify crenation, normal shape, and hemolysis, and explain each result."}, {"n": 10, "name": "Facilitated diffusion", "can": "Describe carrier and channel mediated diffusion and explain why carrier mediated transport shows saturation and specificity while simple diffusion does not."}, {"n": 11, "name": "Primary active transport", "can": "Explain how the sodium potassium ATPase uses ATP to move three sodium out and two potassium in, and state the two gradients it maintains."}, {"n": 12, "name": "Secondary active transport", "can": "Distinguish symport from antiport and trace how the sodium gradient powers glucose uptake by SGLT and calcium removal by the sodium calcium exchanger."}, {"n": 13, "name": "Transport maximum and saturation", "can": "Interpret a transport rate curve, identify the transport maximum, and apply the concept to renal glucose handling in hyperglycemia."}, {"n": 14, "name": "Vesicular transport", "can": "Compare phagocytosis, pinocytosis, receptor mediated endocytosis, and exocytosis by trigger, cargo, and energy requirement."}, {"n": 15, "name": "Transepithelial transport", "can": "Trace glucose or sodium from lumen to blood across a polarized epithelium and identify which step occurs at the apical membrane and which at the basolateral membrane."}, {"n": 16, "name": "Transport simulation", "can": "Use a membrane transport simulation to distinguish simple diffusion from facilitated diffusion and active transport by their response to gradient reversal and metabolic poison."}]}, "4": {"title": "How cells talk, and the electrical signal", "midterm": 1, "items": [{"n": 1, "name": "Ion distribution and electrochemical gradients", "can": "State the typical intracellular and extracellular concentrations of sodium, potassium, chloride, and calcium and separate the chemical from the electrical component of the driving force on each ion."}, {"n": 2, "name": "Nernst equation", "can": "Calculate the equilibrium potential for an ion with the Nernst equation and explain what the sign of the result means for the direction that ion will move."}, {"n": 3, "name": "Resting membrane potential", "can": "Explain why the resting membrane potential sits near the potassium equilibrium potential and predict how it shifts when membrane permeability to potassium or sodium changes."}, {"n": 4, "name": "Ion channel gating", "can": "Compare leak, voltage gated, ligand gated, and mechanically gated channels by what opens each one and give a physiological location for each."}, {"n": 5, "name": "Depolarization and hyperpolarization", "can": "Define depolarization, repolarization, hyperpolarization, and overshoot and label each on a membrane potential tracing."}, {"n": 6, "name": "Membrane potential simulation", "can": "Manipulate extracellular potassium and sodium in a simulation and record the resulting change in resting membrane potential against the Nernst prediction."}, {"n": 7, "name": "Neuron structural and functional classes", "can": "Classify a neuron as multipolar, bipolar, or pseudounipolar by structure and as sensory, motor, or interneuron by function, and match each class to a location in the nervous system."}, {"n": 8, "name": "Functional regions of a neuron", "can": "Label the dendrites, cell body, axon hillock, trigger zone, axon, and axon terminal and state which signal type each region carries."}, {"n": 9, "name": "Glial cell functions", "can": "Match astrocytes, oligodendrocytes, microglia, ependymal cells, satellite cells, and Schwann cells to their physiological roles."}, {"n": 10, "name": "Myelin and its loss", "can": "Explain how myelin and the nodes of Ranvier speed conduction and predict the functional consequence of demyelination."}, {"n": 11, "name": "Axonal transport", "can": "Distinguish fast anterograde and retrograde axonal transport from slow transport and state what each carries."}, {"n": 12, "name": "Graded potentials", "can": "Describe how a graded potential is produced and explain why it varies with stimulus strength and decays with distance, using the terms current leak and cytoplasmic resistance."}, {"n": 13, "name": "Action potential phases", "can": "Diagram an action potential and state the channel state and ion movement responsible for depolarization to peak and for repolarization and afterhyperpolarization."}, {"n": 14, "name": "Threshold and all or none", "can": "Explain what threshold represents at the trigger zone and why action potential amplitude does not change with a stronger stimulus."}, {"n": 15, "name": "Coding of stimulus intensity", "can": "Explain how the nervous system encodes stimulus strength when action potential amplitude is fixed."}, {"n": 16, "name": "Refractory periods", "can": "Distinguish the absolute from the relative refractory period by channel state and explain how the refractory period sets maximum firing frequency and prevents backward conduction."}, {"n": 17, "name": "Conduction velocity", "can": "Rank axons by conduction velocity using diameter and myelination and contrast continuous with saltatory conduction."}, {"n": 18, "name": "Effects of altered extracellular ions", "can": "Predict the effect of hyperkalemia and hypokalemia on resting potential and excitability and explain why local anesthetics that block sodium channels abolish the action potential."}, {"n": 19, "name": "Action potential simulation", "can": "Run a neuron simulation with sodium and potassium channel blockers and interpret the resulting change in the action potential tracing."}, {"n": 20, "name": "Nerve conduction measurement", "can": "Measure conduction velocity from a recorded compound action potential and account for the difference between the fastest and slowest fibers."}]}, "5": {"title": "Synapses and central integration", "midterm": 1, "items": [{"n": 1, "name": "Sequence at a chemical synapse", "can": "Order the events of chemical synaptic transmission from action potential arrival through calcium entry and vesicle fusion to receptor binding and postsynaptic response."}, {"n": 2, "name": "Neurotransmitter classes", "can": "Match acetylcholine, the catecholamines, serotonin, glutamate, GABA, glycine, and the neuropeptides to their usual excitatory or inhibitory effect and to a site of action."}, {"n": 3, "name": "Neurotransmitter removal", "can": "Name the three routes that clear a neurotransmitter from the synaptic cleft, degradation, reuptake, and diffusion, and give a drug that blocks one of them."}, {"n": 4, "name": "Excitatory and inhibitory postsynaptic potentials", "can": "Distinguish an EPSP from an IPSP by the ion channel opened and the direction of the membrane potential change."}, {"n": 5, "name": "Summation and integration", "can": "Distinguish temporal from spatial summation and determine whether a stated combination of EPSPs and IPSPs will bring the trigger zone to threshold."}, {"n": 6, "name": "Presynaptic modulation", "can": "Compare presynaptic inhibition and facilitation with postsynaptic modulation and state the advantage of presynaptic control at a single input, which is selectivity."}, {"n": 7, "name": "Synaptic plasticity", "can": "Explain long term potentiation as a mechanism of learning and identify the roles of repeated stimulation and receptor insertion."}, {"n": 8, "name": "Electrical synapses", "can": "Compare an electrical synapse at a gap junction with a chemical synapse by speed and by capacity for modulation."}, {"n": 9, "name": "Synapse simulation", "can": "Alter neurotransmitter release and receptor availability in a synapse simulation and interpret the resulting postsynaptic recording."}, {"n": 10, "name": "Reflex arc components", "can": "Diagram a reflex arc naming the receptor, sensory neuron, integrating center, motor neuron, and effector, and classify the reflex as monosynaptic or polysynaptic."}, {"n": 11, "name": "Muscle spindle and stretch reflex", "can": "Explain how the muscle spindle detects stretch and trace the stretch reflex including reciprocal inhibition of the antagonist."}, {"n": 12, "name": "Golgi tendon organ", "can": "Contrast the stimulus and the reflex response of the Golgi tendon organ with those of the muscle spindle."}, {"n": 13, "name": "Withdrawal and crossed extensor reflexes", "can": "Trace the flexor withdrawal reflex and the crossed extensor reflex and explain how the two together preserve balance."}, {"n": 14, "name": "Ascending and descending pathways", "can": "Compare the dorsal column, spinothalamic, and corticospinal pathways by the information carried, the side of decussation, and the deficit produced by a lesion."}, {"n": 15, "name": "Cerebrospinal fluid and the blood brain barrier", "can": "State the functions of cerebrospinal fluid and explain how the blood brain barrier selects what reaches neurons, including why lipid soluble drugs cross readily."}, {"n": 16, "name": "Reflex testing and reaction time", "can": "Elicit and grade deep tendon reflexes and measure reaction time to distinguish a reflex response from a voluntary response by latency."}]}, "6": {"title": "Sensing the world, and the responses you do not control", "midterm": 1, "items": [{"n": 1, "name": "Sensory transduction", "can": "Explain how a stimulus is converted into a receptor potential and how that graded potential becomes a train of action potentials in the sensory neuron."}, {"n": 2, "name": "Receptor classification", "can": "Classify a receptor by stimulus type as a mechanoreceptor, chemoreceptor, thermoreceptor, photoreceptor, or nociceptor and give a body location for each."}, {"n": 3, "name": "Stimulus coding", "can": "Explain how the nervous system encodes modality, location, intensity, and duration and identify the labeled line principle."}, {"n": 4, "name": "Receptive fields and acuity", "can": "Relate receptive field size and lateral inhibition to two point discrimination and predict which body regions have the finest acuity."}, {"n": 5, "name": "Receptor adaptation", "can": "Distinguish tonic from phasic receptors by their adaptation rate and match each to a stimulus the body needs to monitor continuously or only at onset."}, {"n": 6, "name": "Somatosensory pathways", "can": "Trace touch and pain information from receptor to cortex and explain why the somatosensory homunculus is disproportionate."}, {"n": 7, "name": "Pain and its modulation", "can": "Distinguish fast and slow pain by fiber type, explain referred pain by convergence, and describe how gate control and endogenous opioids reduce pain transmission."}, {"n": 8, "name": "Tactile mapping and adaptation testing", "can": "Measure two point discrimination at several body sites and show receptor adaptation and referred sensation experimentally."}, {"n": 9, "name": "Optics and accommodation", "can": "Explain refraction by the cornea and lens and describe how accommodation and the pupillary reflex focus near and far images."}, {"n": 10, "name": "Phototransduction", "can": "Trace phototransduction from photon absorption by retinal through the change in cyclic GMP to the decrease in glutamate release and explain why photoreceptors hyperpolarize to light."}, {"n": 11, "name": "Rods cones and visual processing", "can": "Compare rods and cones by sensitivity and acuity and trace the visual pathway to predict the field deficit produced by a lesion at the optic nerve or the optic chiasm."}, {"n": 12, "name": "Refractive errors and clinical vision", "can": "Explain myopia, hyperopia, presbyopia, and astigmatism in terms of focal point and eyeball or lens shape and state the corrective lens for each."}, {"n": 13, "name": "Auditory transduction", "can": "Trace sound from the tympanic membrane through the ossicles and cochlear fluid to hair cell bending and auditory nerve firing and explain how pitch and loudness are coded."}, {"n": 14, "name": "Conductive and sensorineural hearing loss", "can": "Distinguish conductive from sensorineural hearing loss by the site of the lesion and by the expected Weber and Rinne results."}, {"n": 15, "name": "Equilibrium", "can": "Explain how the semicircular canals detect angular acceleration and how the utricle and saccule detect linear acceleration and head position."}, {"n": 16, "name": "Taste and smell", "can": "Compare gustatory and olfactory transduction and explain why olfactory input reaches the limbic system without a thalamic relay."}, {"n": 17, "name": "Vision testing", "can": "Perform visual acuity, blind spot, accommodation, and color vision testing and interpret each result."}, {"n": 18, "name": "Hearing and equilibrium testing", "can": "Perform Weber and Rinne tuning fork tests and a balance test and interpret the findings."}, {"n": 19, "name": "Autonomic and somatic organization", "can": "Contrast the somatic motor system with the autonomic two neuron pathway by neuron count and by effector tissue."}, {"n": 20, "name": "Sympathetic and parasympathetic divisions", "can": "Compare the two autonomic divisions by CNS origin and ganglion location and predict the effect of each on heart rate and on the gastrointestinal tract."}, {"n": 21, "name": "Autonomic neurotransmitters and receptors", "can": "Match nicotinic, muscarinic, alpha, and beta receptors to their neurotransmitter, their location, and the response each produces."}, {"n": 22, "name": "Dual innervation and tonic control", "can": "Explain dual innervation and autonomic tone and predict the effect of removing one division from a dually innervated organ."}, {"n": 23, "name": "Autonomic pharmacology", "can": "Predict the effect of a beta blocker or a muscarinic antagonist on a named organ from the receptor it targets."}, {"n": 24, "name": "Autonomic function testing", "can": "Measure heart rate variability and the response to a cold pressor or orthostatic challenge and interpret the result as sympathetic or parasympathetic dominance."}]}, "7": {"title": "Muscle, and how movement gets commanded", "midterm": 1, "items": [{"n": 1, "name": "Neuromuscular junction", "can": "Trace transmission at the neuromuscular junction from the motor neuron action potential to the end plate potential and explain why every action potential in the motor neuron produces one in the muscle fiber."}, {"n": 2, "name": "Excitation contraction coupling", "can": "Trace excitation contraction coupling from the T tubule through the DHP and ryanodine receptors to calcium release from the sarcoplasmic reticulum."}, {"n": 3, "name": "Crossbridge cycle", "can": "Order the steps of the crossbridge cycle, binding, power stroke, detachment, and reactivation, and state where ATP binds and where it is hydrolyzed."}, {"n": 4, "name": "Calcium and the regulatory proteins", "can": "Explain how calcium binding to troponin moves tropomyosin off the myosin binding site and predict what happens to contraction if calcium cannot be released."}, {"n": 5, "name": "Relaxation and calcium removal", "can": "Explain how SERCA and acetylcholinesterase end a contraction and predict the result if either one fails."}, {"n": 6, "name": "The muscle twitch", "can": "Label the latent period, contraction phase, and relaxation phase on a twitch tracing and explain what limits each phase."}, {"n": 7, "name": "Summation and tetanus", "can": "Explain wave summation and distinguish unfused from fused tetanus by stimulus frequency and calcium accumulation."}, {"n": 8, "name": "Motor units and recruitment", "can": "Define the motor unit and explain how size of the unit and orderly recruitment grade the force a whole muscle produces."}, {"n": 9, "name": "Length tension relationship", "can": "Interpret a length tension curve and explain why tension falls at very short and very long sarcomere lengths."}, {"n": 10, "name": "Isometric and isotonic contraction", "can": "Distinguish isometric, concentric, and eccentric contractions and predict shortening velocity from the load applied."}, {"n": 11, "name": "Muscle fiber types", "can": "Compare slow oxidative, fast oxidative glycolytic, and fast glycolytic fibers by speed, ATP source, fatigue resistance, and typical task."}, {"n": 12, "name": "ATP sources during activity", "can": "Order creatine phosphate, anaerobic glycolysis, and oxidative phosphorylation by how quickly each supplies ATP and how long each can sustain it."}, {"n": 13, "name": "Fatigue and oxygen debt", "can": "Distinguish central from peripheral fatigue and explain the metabolic basis of excess post exercise oxygen consumption."}, {"n": 14, "name": "Muscle plasticity", "can": "Predict the change in fiber size, capillary supply, and mitochondrial content produced by endurance training, resistance training, and disuse."}, {"n": 15, "name": "Electromyography and grip fatigue", "can": "Record grip force and surface EMG over a sustained contraction and relate the decline in force to recruitment and fatigue."}, {"n": 16, "name": "Twitch and tetanus simulation", "can": "Generate twitch and tetanus tracings in a muscle simulation by varying stimulus voltage and frequency and identify threshold and maximal stimulus."}, {"n": 17, "name": "Smooth muscle contraction mechanism", "can": "Trace smooth muscle contraction through calcium entry and release to calmodulin and myosin light chain kinase and explain why the mechanism is slower and more economical than in skeletal muscle."}, {"n": 18, "name": "Smooth muscle types and regulation", "can": "Compare single unit and multi unit smooth muscle and list the stimuli that alter smooth muscle tone including stretch and local chemical signals."}, {"n": 19, "name": "Cardiac muscle properties", "can": "Explain how intercalated discs and gap junctions allow the myocardium to act as a functional syncytium and state why cardiac muscle cannot be tetanized."}, {"n": 20, "name": "Comparison of the three muscle types", "can": "Build a comparison of skeletal, cardiac, and smooth muscle by calcium source, regulatory protein, control, and speed of contraction."}, {"n": 21, "name": "Motor control hierarchy", "can": "Order the levels of motor control from spinal reflex through brainstem to cortex and state what each level contributes to a voluntary movement."}, {"n": 22, "name": "Corticospinal pathway", "can": "Trace the corticospinal pathway from the primary motor cortex to the skeletal muscle and identify where it crosses."}, {"n": 23, "name": "Cerebellum and basal ganglia", "can": "Contrast the contributions of the cerebellum and the basal ganglia to movement and match a described motor sign to the structure involved."}, {"n": 24, "name": "Upper and lower motor neuron signs", "can": "Distinguish upper from lower motor neuron lesions by tone, reflexes, and muscle bulk and assign a set of findings to the correct level."}]}, "8": {"title": "Hormones and reproduction, the slow control system", "midterm": 2, "items": [{"n": 1, "name": "Signal types and range", "can": "Classify a chemical signal as autocrine, paracrine, neurotransmitter, neurohormone, or hormone by its route and distance of travel."}, {"n": 2, "name": "Receptor location and ligand solubility", "can": "Predict whether a signal molecule binds a surface receptor or an intracellular receptor from its lipid solubility and relate that to the speed and duration of the response."}, {"n": 3, "name": "G protein coupled receptors", "can": "Trace a G protein coupled receptor pathway from ligand binding through the G protein and amplifier enzyme to the second messenger and the cellular response."}, {"n": 4, "name": "Second messengers", "can": "Identify cyclic AMP, IP3, diacylglycerol, and calcium as second messengers and state the enzyme that generates each and one target it activates."}, {"n": 5, "name": "Catalytic receptors and intracellular receptors", "can": "Compare a receptor enzyme such as the insulin receptor with an intracellular steroid receptor by mechanism and by time course of the response."}, {"n": 6, "name": "Signal amplification", "can": "Explain how a cascade amplifies a signal and estimate the size of the amplification across the steps of a given pathway."}, {"n": 7, "name": "Receptor modulation", "can": "Define agonist, antagonist, competitive inhibition, up regulation, and down regulation and predict the effect of chronic ligand excess on target cell sensitivity."}, {"n": 8, "name": "Signal termination", "can": "Name three mechanisms that end a chemical signal and explain why a signal that cannot be terminated produces pathology."}, {"n": 9, "name": "Dose response relationships", "can": "Plot a dose response curve, identify threshold, maximal response, and EC50, and compare a full agonist with a partial agonist on the same axes."}, {"n": 10, "name": "Hormone classes", "can": "Classify hormones as peptide, steroid, or amine and compare the three by synthesis, storage, and receptor location."}, {"n": 11, "name": "Hormone transport and half life", "can": "Explain how protein binding in plasma affects the free hormone fraction and the half life and predict which hormone class circulates bound."}, {"n": 12, "name": "Hormone receptors and target response", "can": "Explain why one hormone can produce different responses in different tissues and relate receptor number to target cell sensitivity."}, {"n": 13, "name": "Hormone interactions", "can": "Define synergism, permissiveness, and antagonism and identify each in a described hormone pair."}, {"n": 14, "name": "Control of hormone release", "can": "Classify a hormone stimulus as humoral, neural, or hormonal and trace an example of each."}, {"n": 15, "name": "Hypothalamic pituitary axes", "can": "Trace a three tier axis from hypothalamic releasing hormone through the anterior pituitary trophic hormone to the peripheral gland and place the long and short loop negative feedback."}, {"n": 16, "name": "Primary and secondary endocrine disorders", "can": "Use hormone levels at two tiers of an axis to classify a disorder as primary or secondary and as hypersecretion or hyposecretion."}, {"n": 17, "name": "Posterior pituitary hormones", "can": "Explain why the posterior pituitary is neural tissue and state the stimulus and target action of antidiuretic hormone and oxytocin."}, {"n": 18, "name": "Hormone assay", "can": "Run or simulate an immunoassay for a hormone and use the standard curve to determine an unknown concentration."}, {"n": 19, "name": "Hypothalamic pituitary gonadal axis", "can": "Trace the gonadotropin releasing hormone axis to the gonads and place the feedback loops for both sexes."}, {"n": 20, "name": "Male reproductive physiology", "can": "Explain the control of spermatogenesis by follicle stimulating hormone, luteinizing hormone, and testosterone and state the roles of the Sertoli and Leydig cells."}, {"n": 21, "name": "Ovarian cycle", "can": "Order the follicular, ovulatory, and luteal phases and explain how the luteinizing hormone surge is triggered by positive feedback."}, {"n": 22, "name": "Uterine cycle", "can": "Correlate the menstrual, proliferative, and secretory phases of the uterine cycle with the estrogen and progesterone levels that drive them."}, {"n": 23, "name": "Pregnancy and placental hormones", "can": "Explain how human chorionic gonadotropin rescues the corpus luteum and state the roles of placental estrogen, progesterone, and relaxin."}, {"n": 24, "name": "Parturition and lactation", "can": "Explain labor as a positive feedback loop driven by oxytocin and compare the hormonal control of milk production with milk ejection."}, {"n": 25, "name": "Hormone cycle graph interpretation", "can": "Read a graph of gonadotropin and ovarian hormone levels across a cycle and identify the day of ovulation and the event driving each peak."}]}, "9": {"title": "The heart as a pump", "midterm": 2, "items": [{"n": 1, "name": "Adrenal medulla", "can": "Explain why the adrenal medulla is a modified sympathetic ganglion and compare the duration of its circulating catecholamine effect with direct sympathetic innervation."}, {"n": 2, "name": "Pacemaker potential", "can": "Explain the unstable pacemaker potential of the sinoatrial node by the funny current, calcium entry, and potassium exit and state what sets intrinsic heart rate."}, {"n": 3, "name": "Contractile cell action potential", "can": "Diagram the ventricular action potential and identify the ion movement responsible for the rapid upstroke, the plateau, and repolarization."}, {"n": 4, "name": "Conduction system", "can": "Trace an impulse through the sinoatrial node, internodal pathways, atrioventricular node, bundle of His, bundle branches, and Purkinje fibers and explain the purpose of the atrioventricular delay."}, {"n": 5, "name": "Cardiac refractory period", "can": "Explain why the long refractory period of cardiac muscle prevents tetanus and why that matters for pump function."}, {"n": 6, "name": "ECG waves and intervals", "can": "Label the P wave, QRS complex, T wave, PR interval, and QT interval and state the electrical event each represents."}, {"n": 7, "name": "ECG interpretation", "can": "Calculate heart rate from an ECG strip and identify sinus rhythm, tachycardia, bradycardia, and a first degree or complete heart block."}, {"n": 8, "name": "ECG recording", "can": "Record a lead II ECG, measure the intervals, and correlate each wave with the mechanical event that follows it."}, {"n": 9, "name": "Cardiac cycle", "can": "Order the phases of the cardiac cycle and state the pressure relationship that opens and closes the atrioventricular and semilunar valves in each phase."}, {"n": 10, "name": "Pressure volume loop", "can": "Label the four phases of a ventricular pressure volume loop and predict how the loop changes with increased preload, increased afterload, or increased contractility."}, {"n": 11, "name": "Heart sounds", "can": "Explain the origin of the first and second heart sounds and relate a murmur to valve stenosis or regurgitation by its timing."}, {"n": 12, "name": "Stroke volume and ejection fraction", "can": "Calculate stroke volume and ejection fraction from end diastolic and end systolic volumes and interpret a reduced ejection fraction."}, {"n": 13, "name": "Cardiac output", "can": "Calculate cardiac output and cardiac reserve and predict the effect of a change in heart rate or stroke volume on each."}, {"n": 14, "name": "Frank Starling relationship", "can": "State the Frank Starling law and explain how venous return and end diastolic volume determine the force of the next contraction."}, {"n": 15, "name": "Preload afterload and contractility", "can": "Distinguish preload, afterload, and contractility and predict how a change in each alters stroke volume."}, {"n": 16, "name": "Autonomic regulation of the heart", "can": "Explain how sympathetic and parasympathetic input alter heart rate and contractility at the receptor and second messenger level."}, {"n": 17, "name": "Heart sound and pulse correlation", "can": "Auscultate the heart sounds, locate the valve areas, and correlate the sounds with the pulse and with the cardiac cycle phases."}]}, "10": {"title": "Pressure, flow, and holding blood pressure steady", "midterm": 2, "items": [{"n": 1, "name": "Adrenal cortex", "can": "Match the three cortical zones to aldosterone, cortisol, and the adrenal androgens and state the primary action of each."}, {"n": 2, "name": "Pressure flow and resistance", "can": "Apply the relationship among flow, pressure gradient, and resistance and predict the effect of a change in vessel radius, blood viscosity, or vessel length on flow."}, {"n": 3, "name": "Vessel structure and function", "can": "Match arteries, arterioles, capillaries, venules, and veins to their role in pressure buffering, resistance, exchange, and capacitance."}, {"n": 4, "name": "Arterial blood pressure", "can": "Define systolic, diastolic, pulse, and mean arterial pressure, calculate mean arterial pressure, and explain how it is determined by cardiac output and total peripheral resistance."}, {"n": 5, "name": "Local control of blood flow", "can": "Explain myogenic, metabolic, and endothelial control of arteriolar tone and predict the local flow response to increased tissue metabolism."}, {"n": 6, "name": "Capillary exchange and Starling forces", "can": "Identify the four Starling forces at a capillary and determine the net direction of fluid movement at the arterial and venous ends."}, {"n": 7, "name": "Edema", "can": "Explain how increased capillary hydrostatic pressure, reduced plasma protein, increased permeability, or lymphatic blockage each produce edema and match a clinical scenario to its mechanism."}, {"n": 8, "name": "Venous return", "can": "Explain the skeletal muscle pump, the respiratory pump, and venoconstriction and predict the effect of prolonged standing on venous return and stroke volume."}, {"n": 9, "name": "Blood pressure measurement", "can": "Measure blood pressure by auscultation, explain the origin of the Korotkoff sounds, and record the response to a postural or exercise challenge."}, {"n": 10, "name": "Baroreceptor reflex", "can": "Trace the baroreceptor reflex from the carotid sinus and aortic arch through the medulla to the heart and vessels and state the response to a fall in blood pressure."}, {"n": 11, "name": "Hormonal control of blood pressure", "can": "Describe the roles of angiotensin II, aldosterone, antidiuretic hormone, and atrial natriuretic peptide in long term blood pressure control."}, {"n": 12, "name": "Cardiovascular response to exercise", "can": "Predict the change in heart rate, stroke volume, cardiac output, total peripheral resistance, and regional blood flow distribution during moderate exercise."}, {"n": 13, "name": "Compensation in hemorrhage and shock", "can": "Sequence the compensatory responses to blood loss and explain the point at which compensation fails."}]}, "11": {"title": "Blood and how the body defends itself", "midterm": 2, "items": [{"n": 1, "name": "Plasma and blood functions", "can": "State the three functional categories of blood, transport, regulation, and protection, and name the major plasma proteins and the function of each."}, {"n": 2, "name": "Hematocrit and formed elements", "can": "Define hematocrit and interpret a value as normal or abnormal in the context of anemia and dehydration."}, {"n": 3, "name": "Erythrocyte structure and hemoglobin", "can": "Relate the biconcave shape and absent nucleus of the erythrocyte to its function and describe how the four heme groups of hemoglobin carry oxygen."}, {"n": 4, "name": "Erythropoiesis and its regulation", "can": "Trace the erythropoietin negative feedback loop from tissue hypoxia to increased red cell production and state the nutrients required."}, {"n": 5, "name": "Red cell destruction and bilirubin", "can": "Trace the fate of hemoglobin after red cell breakdown and explain how failure to clear bilirubin produces jaundice."}, {"n": 6, "name": "Leukocytes", "can": "Match neutrophils, lymphocytes, monocytes, eosinophils, and basophils to their defensive function and to the condition that raises each."}, {"n": 7, "name": "Hemostasis", "can": "Order the three phases of hemostasis, vascular spasm, platelet plug formation, and coagulation, and identify the role of von Willebrand factor and thromboxane."}, {"n": 8, "name": "Coagulation cascade", "can": "Compare the intrinsic and extrinsic pathways to the common pathway and identify the roles of thrombin, fibrin, calcium, and vitamin K."}, {"n": 9, "name": "Clot limitation and fibrinolysis", "can": "Explain how anticoagulants and plasmin limit and remove a clot and predict the effect of a drug that blocks vitamin K or platelet aggregation."}, {"n": 10, "name": "ABO and Rh blood types", "can": "Predict agglutination for any donor and recipient ABO and Rh combination and explain the mechanism of hemolytic disease of the newborn."}, {"n": 11, "name": "Hematocrit and hemoglobin determination", "can": "Determine hematocrit and hemoglobin from a sample or simulation and evaluate the result against reference ranges."}, {"n": 12, "name": "Blood typing", "can": "Perform simulated ABO and Rh typing and determine compatible donor types for the result obtained."}, {"n": 13, "name": "Lymphatic return", "can": "State the volume of fluid the lymphatic system returns each day and trace lymph from an interstitial space to the subclavian vein."}, {"n": 14, "name": "Innate defenses", "can": "Describe the physical, chemical, and cellular innate defenses and explain what makes them nonspecific and immediate."}, {"n": 15, "name": "Inflammation and fever", "can": "Order the events of the inflammatory response and explain how the cardinal signs arise and why fever aids defense."}, {"n": 16, "name": "Adaptive immunity", "can": "Compare humoral and cell mediated immunity by the cell responsible, the target, and the mechanism of elimination."}, {"n": 17, "name": "Antibody structure and function", "can": "Relate antibody structure to antigen binding and name the mechanisms by which antibodies neutralize or mark a target."}, {"n": 18, "name": "Immune memory and immunization", "can": "Compare the primary and secondary antibody responses and explain how active and passive immunization produce protection."}, {"n": 19, "name": "Immune dysfunction", "can": "Classify allergy, autoimmunity, and immunodeficiency by what the immune system is doing wrong in each."}]}, "12": {"title": "Digestion, and how you use food for fuel", "midterm": 2, "items": [{"n": 1, "name": "Growth hormone", "can": "Describe the direct and insulin like growth factor mediated actions of growth hormone and predict the result of excess or deficiency before and after epiphyseal closure."}, {"n": 2, "name": "Thyroid hormone", "can": "Trace thyroid hormone synthesis, state the metabolic actions of T3 and T4, and match hyperthyroid and hypothyroid signs to the underlying rate of metabolism."}, {"n": 3, "name": "Cortisol and the stress response", "can": "Describe the metabolic, immune, and cardiovascular actions of cortisol and explain the consequences of chronic elevation."}, {"n": 4, "name": "Pancreatic islet hormones", "can": "Compare insulin and glucagon by stimulus and by effect on liver glycogen and on plasma glucose and identify the islet cell that secretes each."}, {"n": 5, "name": "Diabetes mellitus", "can": "Distinguish type 1 from type 2 diabetes by mechanism and explain how untreated hyperglycemia produces polyuria and ketoacidosis."}, {"n": 6, "name": "Glucose tolerance testing", "can": "Plot a glucose tolerance curve from measured or simulated data and distinguish a normal response from an impaired one."}, {"n": 7, "name": "Four digestive processes", "can": "Distinguish motility, secretion, digestion, and absorption and identify where in the tract each dominates."}, {"n": 8, "name": "Motility patterns", "can": "Compare peristalsis, segmentation, and the migrating motor complex by pattern and purpose."}, {"n": 9, "name": "Neural and hormonal regulation", "can": "Explain short and long reflex control by the enteric nervous system and match gastrin, secretin, cholecystokinin, and glucose dependent insulinotropic peptide to their stimulus and action."}, {"n": 10, "name": "Phases of digestive control", "can": "Describe the cephalic, gastric, and intestinal phases and state the dominant control mechanism in each."}, {"n": 11, "name": "Gastric secretion and mucosal protection", "can": "Trace the production of hydrochloric acid by the parietal cell and explain how the mucosal barrier protects the stomach and how ulcers develop when it fails."}, {"n": 12, "name": "Pancreatic and biliary secretion", "can": "State the components of pancreatic juice and bile and explain how bicarbonate neutralizes chyme and how bile salts emulsify fat."}, {"n": 13, "name": "Carbohydrate and protein digestion and absorption", "can": "Trace a starch and a protein from mouth to bloodstream naming the enzymes at each step and the transport mechanism at the brush border."}, {"n": 14, "name": "Lipid digestion and absorption", "can": "Trace a triglyceride through emulsification, lipase action, micelle formation, and chylomicron packaging to the lymphatic route and explain why fat takes a different path than glucose."}, {"n": 15, "name": "Liver function and enterohepatic circulation", "can": "State the metabolic, storage, and detoxification functions of the liver and trace the enterohepatic circulation of bile salts."}, {"n": 16, "name": "Large intestine and microbiome", "can": "Describe water and electrolyte absorption in the colon, the contribution of the microbiome, and the defecation reflex."}, {"n": 17, "name": "Digestive enzyme experiment", "can": "Test the effect of pH, temperature, and substrate on a digestive enzyme and relate the results to the region of the tract where that enzyme works."}, {"n": 18, "name": "Absorptive state", "can": "Describe the fate of glucose, amino acids, and fats in the absorptive state and identify insulin as the dominant hormone."}, {"n": 19, "name": "Postabsorptive state", "can": "Explain how glycogenolysis, gluconeogenesis, lipolysis, and ketogenesis maintain plasma glucose during fasting and name the hormones that drive each."}, {"n": 20, "name": "Integrated glucose regulation", "can": "Predict the hormonal and metabolic response to a carbohydrate meal and to a prolonged fast and explain how plasma glucose stays within range in both."}, {"n": 21, "name": "Energy balance and metabolic rate", "can": "Define basal metabolic rate, state the factors that raise and lower it, and explain how indirect calorimetry estimates energy expenditure."}, {"n": 22, "name": "Thermoregulation", "can": "Trace the negative feedback response to heat and to cold through the hypothalamus and the effectors and explain the mechanism of fever."}, {"n": 23, "name": "Metabolic rate measurement", "can": "Estimate metabolic rate from measured or simulated oxygen consumption and compare resting values with values after activity."}]}, "13": {"title": "Breathing, gas transport, and the fast pH lever", "midterm": 2, "items": [{"n": 1, "name": "Functions and functional zones", "can": "State the functions of the respiratory system and distinguish the conducting zone from the respiratory zone by structure and by role in gas exchange."}, {"n": 2, "name": "Pressure gradients and airflow", "can": "Apply Boyle's law to inspiration and expiration and relate alveolar pressure to atmospheric pressure at each point in a quiet breath."}, {"n": 3, "name": "Intrapleural pressure", "can": "Explain why intrapleural pressure is subatmospheric and predict what happens to the lung and chest wall when the pleural seal is broken."}, {"n": 4, "name": "Compliance and elastic recoil", "can": "Define lung compliance and elastic recoil and predict the effect of fibrosis and of emphysema on each."}, {"n": 5, "name": "Surfactant and surface tension", "can": "Explain how surfactant lowers surface tension and why its absence causes alveolar collapse in the premature newborn."}, {"n": 6, "name": "Airway resistance", "can": "Identify the main determinant of airway resistance and predict the effect of bronchoconstriction, mucus, and sympathetic stimulation on airflow."}, {"n": 7, "name": "Lung volumes and capacities", "can": "Define tidal volume, inspiratory and expiratory reserve volume, residual volume, vital capacity, and total lung capacity and read each from a spirogram."}, {"n": 8, "name": "Obstructive and restrictive patterns", "can": "Use the ratio of forced expiratory volume in one second to forced vital capacity to classify a spirometry result as obstructive or restrictive."}, {"n": 9, "name": "Alveolar ventilation and dead space", "can": "Calculate minute ventilation and alveolar ventilation and explain why slow deep breathing ventilates the alveoli better than rapid shallow breathing."}, {"n": 10, "name": "Spirometry", "can": "Record a spirogram, calculate the lung volumes and capacities available from it, and compare the results with predicted values."}, {"n": 11, "name": "Partial pressures", "can": "Apply Dalton's law to calculate the partial pressure of oxygen in inspired and alveolar air and state the normal partial pressures in alveolar air, arterial blood, and venous blood."}, {"n": 12, "name": "Diffusion at the respiratory membrane", "can": "Apply the determinants of diffusion to the respiratory membrane and predict the effect of edema, fibrosis, and emphysema on gas transfer."}, {"n": 13, "name": "Ventilation perfusion matching", "can": "Explain how local hypoxic vasoconstriction and bronchiolar responses match ventilation to perfusion and predict the consequence of a mismatch."}, {"n": 14, "name": "Oxygen transport and the oxyhemoglobin curve", "can": "Explain the sigmoid shape of the oxyhemoglobin dissociation curve and state the physiological advantage of the steep and the flat portions."}, {"n": 15, "name": "Curve shifts", "can": "Predict the direction of the oxyhemoglobin curve shift produced by a change in pH, carbon dioxide, temperature, or 2,3 bisphosphoglycerate and state what the shift means for tissue oxygen delivery."}, {"n": 16, "name": "Carbon dioxide transport", "can": "Name the three forms in which carbon dioxide is carried, state the approximate percentage of each, and trace the chloride shift in a systemic capillary."}, {"n": 17, "name": "Bohr and Haldane effects", "can": "Distinguish the Bohr effect from the Haldane effect and explain how the two work together at the tissue and at the lung."}, {"n": 18, "name": "Oxygen content versus partial pressure", "can": "Distinguish oxygen content from oxygen partial pressure and saturation and explain why anemia and carbon monoxide poisoning reduce delivery differently."}, {"n": 19, "name": "Respiratory centers", "can": "Identify the medullary and pontine respiratory centers and explain how the basic breathing rhythm is generated and modified."}, {"n": 20, "name": "Chemoreceptor control", "can": "Compare central and peripheral chemoreceptors by stimulus and explain why carbon dioxide is the primary minute to minute drive to breathe."}, {"n": 21, "name": "Ventilation in exercise and at altitude", "can": "Predict the ventilatory response to exercise and to acute and chronic altitude exposure and explain the acclimatization changes."}, {"n": 22, "name": "Ventilatory response testing", "can": "Measure the change in breathing rate and depth after hyperventilation, breath holding, and rebreathing and explain each result by the change in carbon dioxide."}, {"n": 23, "name": "Buffer systems", "can": "Compare the bicarbonate, phosphate, and protein buffer systems by location and speed and explain why bicarbonate is the dominant extracellular buffer."}, {"n": 24, "name": "Respiratory control of pH", "can": "Explain how a change in ventilation shifts the carbon dioxide and bicarbonate equilibrium and therefore plasma pH."}]}, "14": {"title": "The kidney and body fluid balance", "midterm": 2, "items": [{"n": 1, "name": "Calcium homeostasis", "can": "Trace the response to falling plasma calcium through parathyroid hormone, calcitriol, and the actions on bone, kidney, and intestine, and state the role of calcitonin."}, {"n": 2, "name": "Kidney functions", "can": "List the homeostatic functions of the kidney including water and electrolyte balance, acid base regulation, waste excretion, blood pressure control, and hormone production."}, {"n": 3, "name": "Nephron structure and function", "can": "Match each nephron segment to its dominant transport function and distinguish a cortical from a juxtamedullary nephron by capability."}, {"n": 4, "name": "Three renal processes", "can": "Define filtration, reabsorption, secretion, and excretion and write the equation that relates them for any solute."}, {"n": 5, "name": "Filtration membrane and selectivity", "can": "Describe the three layers of the filtration membrane and predict which plasma components appear in the filtrate based on size and charge."}, {"n": 6, "name": "Net filtration pressure and GFR", "can": "Calculate net filtration pressure from glomerular hydrostatic pressure, capsular pressure, and colloid osmotic pressure and predict the effect of each change on glomerular filtration rate."}, {"n": 7, "name": "Regulation of GFR", "can": "Compare myogenic autoregulation, tubuloglomerular feedback, sympathetic control, and hormonal control and predict the effect of afferent and efferent arteriolar constriction on filtration rate."}, {"n": 8, "name": "Renal clearance", "can": "Calculate the clearance of a substance and use inulin and creatinine clearance to estimate glomerular filtration rate."}, {"n": 9, "name": "Clearance and handling inference", "can": "Use a clearance value relative to glomerular filtration rate to determine whether a substance is net reabsorbed or net secreted."}, {"n": 10, "name": "Proximal tubule reabsorption", "can": "Explain how the sodium gradient drives reabsorption of glucose, amino acids, and water in the proximal tubule and state why reabsorption there is described as isosmotic."}, {"n": 11, "name": "Transport maximum and renal threshold", "can": "Distinguish transport maximum from renal threshold and explain the appearance of glucose in urine when plasma glucose is elevated."}, {"n": 12, "name": "Tubular secretion", "can": "State the purpose of tubular secretion and name substances secreted including hydrogen ion, potassium, and organic anions such as drugs."}, {"n": 13, "name": "Countercurrent mechanism", "can": "Explain how the countercurrent multiplier of the loop of Henle and the countercurrent exchanger of the vasa recta build and preserve the medullary osmotic gradient."}, {"n": 14, "name": "Antidiuretic hormone and urine concentration", "can": "Trace the response to dehydration from osmoreceptor firing through antidiuretic hormone release to aquaporin insertion and concentrated urine."}, {"n": 15, "name": "Renin angiotensin aldosterone system", "can": "Trace the renin angiotensin aldosterone pathway from the stimulus for renin release to the effects of angiotensin II and aldosterone on vessels, tubules, and blood pressure."}, {"n": 16, "name": "Natriuretic peptides", "can": "Explain how atrial natriuretic peptide opposes the renin angiotensin aldosterone system and state the stimulus for its release."}, {"n": 17, "name": "Potassium handling", "can": "Explain how aldosterone and plasma potassium regulate potassium secretion in the collecting duct and predict the effect of a potassium wasting diuretic."}, {"n": 18, "name": "Micturition", "can": "Trace the micturition reflex and explain how the internal and external sphincters allow voluntary control."}, {"n": 19, "name": "Urinalysis", "can": "Perform a urinalysis measuring specific gravity, pH, glucose, protein, ketones, and blood and relate any abnormal finding to the renal process that failed."}, {"n": 20, "name": "Renal function calculation", "can": "Calculate glomerular filtration rate, clearance, and filtered load from a data set and interpret the values in a clinical case."}, {"n": 21, "name": "Volume and osmolarity disturbances", "can": "Classify a disturbance as volume depletion or overload and as hypoosmotic, isosmotic, or hyperosmotic and predict the resulting fluid shift between compartments."}]}, "15": {"title": "The slow pH lever, and putting it all together", "midterm": null, "items": [{"n": 1, "name": "Renal control of pH", "can": "Describe how the kidney secretes hydrogen ion and reclaims or generates bicarbonate and explain why renal compensation is slower and more complete than respiratory compensation."}, {"n": 2, "name": "The four acid base disorders", "can": "Classify a disorder as respiratory or metabolic and as acidosis or alkalosis from pH, partial pressure of carbon dioxide, and bicarbonate."}, {"n": 3, "name": "Compensation", "can": "Determine whether an acid base disorder is uncompensated, partially compensated, or fully compensated and name the system doing the compensating."}, {"n": 4, "name": "Arterial blood gas interpretation", "can": "Interpret a set of arterial blood gas values and match the result to a plausible clinical cause."}, {"n": 5, "name": "Multisystem integration case", "can": "Given a clinical scenario, trace the disturbance through at least three organ systems and identify the compensatory responses in the order they occur."}, {"n": 6, "name": "Exercise as an integrated response", "can": "Build an integrated account of moderate exercise across the muscular, cardiovascular, respiratory, endocrine, and renal systems."}, {"n": 7, "name": "Drawing based synthesis check", "can": "Draw and annotate a homeostatic pathway from memory and explain each step aloud or in writing without notes."}]}};
